import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';

/**
 * The prepared Adilo course import (production/content/adilo, generated by build.py) must account for every
 * Adilo video exactly once, in its own course, in the original Adilo order.
 */
const dir = new URL('../production/content/adilo/', import.meta.url);
const inv = JSON.parse(fs.readFileSync(new URL('adilo-inventory.raw.json', dir), 'utf8')) as { rows: [string, string, string, number][]; excludedProjects: { id: string }[] };
const data = JSON.parse(fs.readFileSync(new URL('courses.json', dir), 'utf8')) as {
  courses: { id: string; slug: string; title: string; adiloProject: string; videoCount: number; thumbnail: string; sections: { id: string; title: string; description: string; lessons: { id: string; number: string; title: string; adiloFileId: string; originalTitle: string; durationSeconds: number }[] }[] }[];
};
const num = (n: string) => (n === 'Intro' ? -1 : parseInt(n, 10));
const originalNumber = (t: string) => (/^\s*(\d+[A-Za-z]?)\s*[.\s]/.exec(t)?.[1].toUpperCase() ?? 'Intro');

test('every Adilo video of the included courses is imported exactly once, in its own course', () => {
  const byProject = new Map<string, string[]>();
  for (const [pid, vid] of inv.rows) byProject.set(pid, [...(byProject.get(pid) || []), vid]);
  const seen = new Set<string>();
  for (const c of data.courses) {
    const vids = c.sections.flatMap((s) => s.lessons.map((l) => l.adiloFileId));
    for (const v of vids) {
      assert.ok(!seen.has(v), `${v} imported twice`);
      seen.add(v);
    }
    assert.deepEqual([...vids].sort(), [...(byProject.get(c.adiloProject) || [])].sort(), `${c.title}: videos differ from Adilo project ${c.adiloProject}`);
    assert.equal(c.videoCount, vids.length);
  }
  assert.equal(seen.size, inv.rows.length, 'no video missing');
  assert.ok(!data.courses.some((c) => inv.excludedProjects.some((p) => p.id === c.adiloProject)), 'excluded projects are not imported');
});

test('original Adilo numbering and order are kept, and lesson titles show the number', () => {
  for (const c of data.courses) {
    const lessons = c.sections.flatMap((s) => s.lessons);
    const nums = lessons.map((l) => l.number);
    assert.deepEqual(nums, [...nums].sort((a, b) => num(a) - num(b) || a.localeCompare(b)), `${c.title}: order changed`);
    for (const l of lessons) {
      assert.equal(l.number, originalNumber(l.originalTitle), `${c.title}: ${l.title} number differs from Adilo`);
      if (l.number !== 'Intro') assert.ok(l.title.startsWith(`${l.number}. `), l.title);
      assert.ok(l.durationSeconds > 0);
    }
    assert.equal(new Set(lessons.map((l) => l.id)).size, lessons.length, 'unique lesson ids');
  }
});

test('courses have unique readable slugs, titles, section overviews and a branded thumbnail', () => {
  const slugs = data.courses.map((c) => c.slug);
  assert.equal(new Set(slugs).size, slugs.length);
  assert.equal(new Set(data.courses.map((c) => c.title)).size, data.courses.length);
  for (const c of data.courses) {
    assert.match(c.slug, /^[a-z0-9]+(-[a-z0-9]+)*$/);
    for (const s of c.sections) {
      assert.ok(s.description.length > 20, `${c.title}: ${s.title} needs an overview`);
      assert.doesNotMatch(s.title, /^(section \d+|other topics|misc)/i);
    }
    const file = new URL(`../public/images/courses/${c.slug}.jpg`, import.meta.url);
    if (!c.id.startsWith('course-adilo-')) continue; // existing courses keep their designed thumbnail (logo added on apply)
    assert.equal(c.thumbnail, `https://edufyacademy.com/images/courses/${c.slug}.jpg`);
    assert.ok(fs.existsSync(file), `missing thumbnail ${c.slug}.jpg`);
    const buf = fs.readFileSync(file);
    assert.equal(buf.readUInt16BE(0), 0xffd8, 'JPEG');
    assert.ok(buf.length < 200 * 1024, 'optimised size');
  }
});
